import type { ComponentType, ReactNode } from "react"

type ChartSeriesTheme = { light: string; dark: string }

type ChartSeriesConfig = {
  label?: ReactNode
  icon?: ComponentType<{ className?: string }>
} & ({ color?: string; theme?: never } | { color?: never; theme: ChartSeriesTheme })

type ChartConfig = Record<string, ChartSeriesConfig>

type ChartName =
  | { "aria-label": string; "aria-labelledby"?: string }
  | { "aria-label"?: string; "aria-labelledby": string }

type ChartFormat = Intl.NumberFormatOptions | ((value: number) => string)

interface ChartFormatOptions {
  locale?: string
  format?: ChartFormat
}

const seriesKeyPattern = /^[\w-]+$/
// Colors are written into a <style> element, so a value that could end the declaration or the element is dropped.
const unsafeColor = /[;{}<>\\]/

function chartColorDeclarations(config: ChartConfig, mode: keyof ChartSeriesTheme) {
  const declarations: string[] = []
  for (const [key, series] of Object.entries(config)) {
    const color = series.theme?.[mode] ?? series.color
    if (!color || !seriesKeyPattern.test(key) || unsafeColor.test(color)) continue
    declarations.push(`--color-${key}: ${color};`)
  }
  return declarations
}

function chartStyleSheet(config: ChartConfig, chartId: string) {
  const scope = `[data-chart="${chartId.replaceAll(/[^\w-]/g, "")}"]`
  const light = chartColorDeclarations(config, "light")
  const dark = chartColorDeclarations(config, "dark")
  const rules = []
  if (light.length > 0) rules.push(`${scope} { ${light.join(" ")} }`)
  if (dark.join() !== light.join() && dark.length > 0) rules.push(`.dark ${scope}, ${scope}.dark { ${dark.join(" ")} }`)
  return rules.join("\n")
}

function formatChartValue(value: unknown, { locale, format }: ChartFormatOptions = {}) {
  if (typeof value !== "number") return value == null ? "" : String(value)
  if (typeof format === "function") return format(value)
  return new Intl.NumberFormat(locale, format).format(value)
}

type ChartPayloadItem = { dataKey?: unknown; name?: unknown; payload?: unknown }

// A pie's payload names its series in a data field (nameKey), so that field's value is the config key.
function resolveChartSeries(config: ChartConfig, item: ChartPayloadItem | undefined, key: string) {
  const own = item as Record<string, unknown> | undefined
  const row = item?.payload as Record<string, unknown> | undefined
  let configKey = key
  if (typeof own?.[key] === "string") configKey = own[key] as string
  else if (typeof row?.[key] === "string") configKey = row[key] as string
  return { key: configKey, series: config[configKey] ?? config[key] }
}

// A series filled with an SVG pattern reports url(#id), which a CSS background can't paint, so its swatch uses the series color.
function chartSwatchColor(config: ChartConfig, key: string, color: string | undefined) {
  if (color && !color.startsWith("url(")) return color
  const series = config[key]
  return series?.color || series?.theme ? `var(--color-${key})` : color
}

export { chartStyleSheet, chartSwatchColor, formatChartValue, resolveChartSeries }
export type { ChartConfig, ChartFormat, ChartFormatOptions, ChartName, ChartSeriesConfig, ChartSeriesTheme }

"use client"

import { createContext, use } from "react"

import type { ChartConfig } from "@/lib/chart-config"

const ChartContext = createContext<{ config: ChartConfig } | null>(null)

function useChart() {
  const context = use(ChartContext)
  if (!context) throw new Error("Chart parts must be rendered inside a <ChartContainer />")
  return context
}

export { ChartContext, useChart }

"use client"

import type { CSSProperties, ReactNode } from "react"
import type { TooltipPayloadEntry } from "recharts"

import { useLocale } from "@/lib/locale"
import { chartSwatchColor, formatChartValue, resolveChartSeries, type ChartFormatOptions } from "@/lib/chart-config"
import { cn } from "@/lib/utils"
import { useChart } from "@/components/ui/chart-context"

type ChartIndicator = "dot" | "line" | "dashed"

// Recharts clones the content with every Tooltip prop, so only these are read and nothing is spread onto the DOM.
type ChartTooltipContentProps = ChartFormatOptions & {
  active?: boolean
  payload?: readonly TooltipPayloadEntry[]
  label?: string | number
  labelKey?: string
  nameKey?: string
  indicator?: ChartIndicator
  hideLabel?: boolean
  hideIndicator?: boolean
  color?: string
  labelFormatter?: (label: ReactNode, payload: readonly TooltipPayloadEntry[]) => ReactNode
  formatter?: (value: unknown, name: unknown, item: TooltipPayloadEntry, index: number) => ReactNode
  className?: string
  labelClassName?: string
}

const tooltipSurfaceClassName =
  "grid min-w-32 items-start gap-inline rounded-lg border border-floating-border bg-floating px-inset-item py-inset-item text-xs text-popover-foreground shadow-floating backdrop-floating"

const indicatorClassName =
  "shrink-0 rounded-xs border-(--indicator-color) bg-(--indicator-color) data-[indicator=dot]:size-2.5 data-[indicator=line]:w-1 data-[indicator=dashed]:w-0 data-[indicator=dashed]:border-2 data-[indicator=dashed]:border-dashed data-[indicator=dashed]:bg-transparent"

function ChartTooltipContent({
  active,
  payload,
  label,
  labelKey,
  nameKey,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  color,
  locale: localeProp,
  format,
  labelFormatter,
  formatter,
  className,
  labelClassName,
}: ChartTooltipContentProps) {
  const { config } = useChart()
  const locale = useLocale(localeProp)
  const items = (payload ?? []).filter((item) => item.type !== "none")
  if (!active || items.length === 0) return null

  const first = items[0]
  const firstKey = labelKey ?? String(first?.dataKey ?? first?.name ?? "value")
  const labelSeries = resolveChartSeries(config, first, firstKey).series
  const labelValue =
    !labelKey && (typeof label === "string" || typeof label === "number")
      ? (config[String(label)]?.label ?? label)
      : labelSeries?.label
  const labelContent = labelFormatter ? labelFormatter(labelValue, items) : labelValue
  const labelNode =
    hideLabel || labelContent == null || labelContent === "" ? null : (
      <div data-slot="chart-tooltip-label" className={cn("font-medium", labelClassName)}>
        {labelContent}
      </div>
    )
  const nested = items.length === 1 && indicator !== "dot"

  return (
    <div data-slot="chart-tooltip" className={cn(tooltipSurfaceClassName, className)}>
      {nested ? null : labelNode}
      <div className="grid gap-inline">
        {items.map((item, index) => {
          const key = nameKey ?? String(item.name ?? item.dataKey ?? "value")
          const { key: seriesKey, series } = resolveChartSeries(config, item, key)
          const row = item.payload as { fill?: string } | undefined
          const indicatorColor = color ?? chartSwatchColor(config, seriesKey, row?.fill ?? item.color)
          const Icon = series?.icon
          return (
            <div
              key={`${String(item.dataKey ?? item.name)}-${item.graphicalItemId}`}
              data-slot="chart-tooltip-item"
              className={cn("flex w-full flex-wrap items-stretch gap-inline", indicator === "dot" && "items-center")}
            >
              {formatter && item.value !== undefined ? (
                formatter(item.value, item.name, item, index)
              ) : (
                <>
                  {Icon ? <Icon className="size-3 text-muted-foreground" /> : null}
                  {!Icon && !hideIndicator ? (
                    <div
                      data-slot="chart-indicator"
                      data-indicator={indicator}
                      aria-hidden="true"
                      style={{ "--indicator-color": indicatorColor } as CSSProperties}
                      // oxlint-disable-next-line p-otero/spacing-tokens -- centres the dashed bar on the label's line
                      className={cn(indicatorClassName, nested && indicator === "dashed" && "my-0.5")}
                    />
                  ) : null}
                  <div
                    className={cn(
                      "flex flex-1 justify-between gap-items leading-none",
                      nested ? "items-end" : "items-center",
                    )}
                  >
                    <div className="grid gap-inline">
                      {nested ? labelNode : null}
                      <span className="text-muted-foreground">{series?.label ?? item.name}</span>
                    </div>
                    {item.value == null ? null : (
                      <span className="font-mono font-medium text-popover-foreground tabular-nums">
                        {formatChartValue(item.value, { locale, format })}
                      </span>
                    )}
                  </div>
                </>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}

export { ChartTooltipContent }
export type { ChartIndicator, ChartTooltipContentProps }

"use client"

import type { CSSProperties } from "react"
import type { LegendPayload } from "recharts"

import { chartSwatchColor, resolveChartSeries } from "@/lib/chart-config"
import { cn } from "@/lib/utils"
import { useChart } from "@/components/ui/chart-context"

// Recharts clones the content with every Legend prop, so only these are read and nothing is spread onto the DOM.
type ChartLegendContentProps = {
  className?: string
  payload?: readonly LegendPayload[]
  verticalAlign?: "top" | "middle" | "bottom"
  nameKey?: string
  hideIcon?: boolean
}

function ChartLegendContent({
  payload,
  verticalAlign = "bottom",
  nameKey,
  hideIcon = false,
  className,
}: ChartLegendContentProps) {
  const { config } = useChart()
  const items = (payload ?? []).filter((item) => item.type !== "none")
  if (items.length === 0) return null
  return (
    <ul
      data-slot="chart-legend"
      className={cn(
        "flex flex-wrap items-center justify-center gap-x-group gap-y-items text-xs",
        verticalAlign === "top" ? "pb-group" : "pt-group",
        className,
      )}
    >
      {items.map((item) => {
        const key = nameKey ?? String(item.dataKey ?? item.value ?? "value")
        const { key: seriesKey, series } = resolveChartSeries(config, item, key)
        const Icon = series?.icon
        return (
          <li key={seriesKey} data-slot="chart-legend-item" className="flex items-center gap-inline">
            {Icon && !hideIcon ? <Icon className="size-3 text-muted-foreground" /> : null}
            {!Icon && !hideIcon ? (
              <span
                aria-hidden="true"
                data-slot="chart-legend-swatch"
                style={{ "--indicator-color": chartSwatchColor(config, seriesKey, item.color) } as CSSProperties}
                className="size-2.5 shrink-0 rounded-xs bg-(--indicator-color)"
              />
            ) : null}
            <span>{series?.label ?? item.value}</span>
          </li>
        )
      })}
    </ul>
  )
}

export { ChartLegendContent }
export type { ChartLegendContentProps }

"use client"

import { use, type ReactNode } from "react"

import { useLocale } from "@/lib/locale"
import { formatChartValue, type ChartConfig, type ChartFormatOptions, type ChartName } from "@/lib/chart-config"
import { ChartContext } from "@/components/ui/chart-context"
import { Table, TableBody, TableCaption, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"

/** Any row object; an `interface` works too, since rows don't need an index signature. */
type ChartRow = object

type ChartDataTableProps<TRow extends ChartRow> = ChartName &
  ChartFormatOptions & {
    data: readonly TRow[]
    /** The field that names each row, like a month. */
    labelKey: keyof TRow & string
    /** The value columns, in order; by default the config's series that hold a number. */
    keys?: readonly (keyof TRow & string)[]
    config?: ChartConfig
    caption?: ReactNode
    visuallyHidden?: boolean
    className?: string
  }

function ChartDataTable<TRow extends ChartRow>({
  data,
  labelKey,
  keys,
  config: configProp,
  caption,
  visuallyHidden = true,
  locale: localeProp,
  format,
  className,
  ...name
}: ChartDataTableProps<TRow>) {
  const config = configProp ?? use(ChartContext)?.config ?? {}
  const locale = useLocale(localeProp)
  const rows = data as readonly Record<string, unknown>[]
  const columns: readonly string[] =
    keys ?? Object.keys(config).filter((key) => key !== labelKey && rows.some((row) => typeof row[key] === "number"))
  const headerFor = (key: string) => config[key]?.label ?? key

  const table = (
    <Table {...name} className={className}>
      {caption ? <TableCaption>{caption}</TableCaption> : null}
      <TableHeader>
        <TableRow>
          <TableHead scope="col">{headerFor(labelKey)}</TableHead>
          {columns.map((key) => (
            <TableHead key={key} scope="col" className="text-end">
              {headerFor(key)}
            </TableHead>
          ))}
        </TableRow>
      </TableHeader>
      <TableBody>
        {rows.map((row) => {
          const category = String(row[labelKey] ?? "")
          return (
            <TableRow key={category}>
              <TableHead scope="row">{config[category]?.label ?? category}</TableHead>
              {columns.map((key) => (
                <TableCell key={key} className="text-end tabular-nums">
                  {formatChartValue(row[key], { locale, format })}
                </TableCell>
              ))}
            </TableRow>
          )
        })}
      </TableBody>
    </Table>
  )

  if (!visuallyHidden) return <div data-slot="chart-data-table">{table}</div>
  // The inner box sizes to the table, so the scroll area never overflows and never adds a tab stop nobody can see.
  return (
    <div data-slot="chart-data-table" data-visually-hidden="" className="sr-only">
      <div className="w-max">{table}</div>
    </div>
  )
}

export { ChartDataTable }
export type { ChartDataTableProps, ChartRow }

"use client"

import { useId, type ComponentProps, type ReactNode } from "react"
import { Legend, ResponsiveContainer, Tooltip } from "recharts"

import {
  chartStyleSheet,
  type ChartConfig,
  type ChartName,
  type ChartFormat,
  type ChartSeriesConfig,
} from "@/lib/chart-config"
import { cn } from "@/lib/utils"
import { ChartContext, useChart } from "@/components/ui/chart-context"
import { ChartTooltipContent, type ChartTooltipContentProps } from "@/components/ui/chart-tooltip"
import { ChartLegendContent, type ChartLegendContentProps } from "@/components/ui/chart-legend"
import { ChartDataTable, type ChartDataTableProps } from "@/components/ui/chart-data-table"

// Recharts paints grid, axis and cursor with fixed hex colors; these map them to theme tokens.
// The focus ring stays on the keyboard-focusable surface the accessibility layer adds.
const rechartsClassName = [
  "[&_.recharts-cartesian-axis-tick-value]:fill-muted-foreground",
  "[&_.recharts-polar-angle-axis-tick-value]:fill-muted-foreground [&_.recharts-polar-radius-axis-tick-value]:fill-muted-foreground",
  "[&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border",
  "[&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border",
  "[&_.recharts-reference-line_[stroke='#ccc']]:stroke-border",
  "[&_.recharts-curve.recharts-tooltip-cursor]:stroke-border",
  "[&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted",
  "[&_.recharts-radial-bar-background-sector]:fill-muted",
  "[&_.recharts-dot[stroke='#fff']]:stroke-transparent",
  "[&_.recharts-sector]:outline-hidden [&_.recharts-layer]:outline-hidden",
  "[&_.recharts-surface]:rounded-sm [&_.recharts-surface]:outline-hidden",
  "[&_.recharts-surface:focus-visible]:outline-2 [&_.recharts-surface:focus-visible]:outline-offset-2 [&_.recharts-surface:focus-visible]:outline-ring",
].join(" ")

type ChartContainerProps = Omit<ComponentProps<"figure">, "children" | "aria-label" | "aria-labelledby"> &
  ChartName & {
    config: ChartConfig
    children: ReactNode
    initialDimension?: { width: number; height: number }
  }

function ChartStyle({ id, config }: { id: string; config: ChartConfig }) {
  const css = chartStyleSheet(config, id)
  return css ? <style data-slot="chart-style">{css}</style> : null
}

function ChartContainer({ id, config, className, children, initialDimension, ...props }: ChartContainerProps) {
  const generatedId = useId()
  const chartId = `chart-${(id ?? generatedId).replaceAll(/[^\w-]/g, "")}`
  return (
    <ChartContext value={{ config }}>
      <figure
        id={id}
        data-slot="chart"
        data-chart={chartId}
        className={cn("relative flex aspect-video w-full justify-center text-xs", rechartsClassName, className)}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <ResponsiveContainer initialDimension={initialDimension}>{children}</ResponsiveContainer>
      </figure>
    </ChartContext>
  )
}

const ChartTooltip = Tooltip
const ChartLegend = Legend

export { ChartContainer, ChartLegend, ChartStyle, ChartTooltip }
export { ChartTooltipContent }
export { ChartLegendContent }
export { ChartDataTable }
export { useChart }
export type { ChartContainerProps }
export type { ChartTooltipContentProps }
export type { ChartLegendContentProps }
export type { ChartDataTableProps }
export type { ChartConfig, ChartFormat, ChartSeriesConfig }
